package cn.medreminder.app;
import java.time.*;import java.util.*;
/** Behavioral acceptance for the sticky Today focus controller. */
public final class TodayFocusRegressionTest {
 static void eq(long a,long b){if(a!=b)throw new AssertionError("expected "+a+" but was "+b);}
 public static void main(String[] args){ZoneId z=ZoneId.of("Asia/Shanghai");LocalDate d=LocalDate.of(2026,11,8);long init=d.atTime(7,50).atZone(z).toInstant().toEpochMilli(),observe=d.atTime(8,20).atZone(z).toInstant().toEpochMilli();Store.Med m=med(11,1,"08:00,20:00");FileState disk=new FileState(new java.io.File(".work-v13/focus-state.txt"));disk.put("");TodayFocus focus=new TodayFocus(disk);List<Store.Med> meds=Arrays.asList(m);TodayPlan first=focus.apply(TodayPlan.build(meds,Collections.emptyList(),Collections.emptyList(),init,z.getId()),meds,Collections.emptyList(),Collections.emptyList(),init,z.getId());eq(d.atTime(8,0).atZone(z).toInstant().toEpochMilli(),first.hero.get(0).plannedAt);TodayFocus reopened=new TodayFocus(new FileState(new java.io.File(".work-v13/focus-state.txt")));TodayPlan crossed=reopened.apply(TodayPlan.build(meds,Collections.emptyList(),Collections.emptyList(),observe,z.getId()),meds,Collections.emptyList(),Collections.emptyList(),observe,z.getId());eq(d.atTime(8,0).atZone(z).toInstant().toEpochMilli(),crossed.hero.get(0).plannedAt);Memory memory=new Memory();
 long midnight=d.atTime(23,50).atZone(z).toInstant().toEpochMilli();m=med(12,1,"23:50");memory=new Memory();meds=Arrays.asList(m);focus=new TodayFocus(memory);TodayPlan night=focus.apply(TodayPlan.build(meds,Collections.emptyList(),Collections.emptyList(),midnight,z.getId()),meds,Collections.emptyList(),Collections.emptyList(),midnight,z.getId());eq(midnight,night.hero.get(0).plannedAt);long after=d.plusDays(1).atTime(0,15).atZone(z).toInstant().toEpochMilli();crossed=new TodayFocus(memory).apply(TodayPlan.build(meds,Collections.emptyList(),Collections.emptyList(),after,z.getId()),meds,Collections.emptyList(),Collections.emptyList(),after,z.getId());eq(midnight,crossed.hero.get(0).plannedAt);
 m=med(13,1,"08:00,12:00,20:00");memory=new Memory();meds=Arrays.asList(m);long midday=d.atTime(13,0).atZone(z).toInstant().toEpochMilli();focus=new TodayFocus(memory);first=focus.apply(TodayPlan.build(meds,Collections.emptyList(),Collections.emptyList(),midday,z.getId()),meds,Collections.emptyList(),Collections.emptyList(),midday,z.getId());eq(d.atTime(12,0).atZone(z).toInstant().toEpochMilli(),first.hero.get(0).plannedAt);
 m=med(14,1,"08:00");Store.Med m2=med(15,1,"08:00");meds=Arrays.asList(m,m2);memory=new Memory();focus=new TodayFocus(memory);long at=d.atTime(8,0).atZone(z).toInstant().toEpochMilli();first=focus.apply(TodayPlan.build(meds,Collections.emptyList(),Collections.emptyList(),at,z.getId()),meds,Collections.emptyList(),Collections.emptyList(),at,z.getId());eq(2,first.hero.size());Store.Log done=new Store.Log();done.medId=14;done.plannedAt=at;List<Store.Log> logs=Arrays.asList(done);crossed=new TodayFocus(memory).apply(TodayPlan.build(meds,logs,Collections.emptyList(),at+1,z.getId()),meds,logs,Collections.emptyList(),at+1,z.getId());eq(1,crossed.hero.size());eq(15,crossed.hero.get(0).med.id);eq(1,crossed.completed.size());eq(1,crossed.pending());
 m=med(16,1,"08:00,12:00");meds=Arrays.asList(m);memory=new Memory();focus=new TodayFocus(memory);first=focus.apply(TodayPlan.build(meds,Collections.emptyList(),Collections.emptyList(),init,z.getId()),meds,Collections.emptyList(),Collections.emptyList(),init,z.getId());Store.Med revised=med(16,2,"08:00,12:00");meds=Arrays.asList(revised);crossed=new TodayFocus(memory).apply(TodayPlan.build(meds,Collections.emptyList(),Collections.emptyList(),observe,z.getId()),meds,Collections.emptyList(),Collections.emptyList(),observe,z.getId());eq(d.atTime(8,0).atZone(z).toInstant().toEpochMilli(),crossed.hero.get(0).plannedAt);eq(2,crossed.hero.get(0).med.revision);
 Store.Med rescheduled=med(16,3,"09:00,12:00");meds=Arrays.asList(rescheduled);crossed=new TodayFocus(memory).apply(TodayPlan.build(meds,Collections.emptyList(),Collections.emptyList(),observe,z.getId()),meds,Collections.emptyList(),Collections.emptyList(),observe,z.getId());eq(d.atTime(9,0).atZone(z).toInstant().toEpochMilli(),crossed.hero.get(0).plannedAt);
 m=med(17,1,"08:00,09:00,12:00,20:00");meds=Arrays.asList(m);memory=new Memory();focus=new TodayFocus(memory);first=focus.apply(TodayPlan.build(meds,Collections.emptyList(),Collections.emptyList(),init,z.getId()),meds,Collections.emptyList(),Collections.emptyList(),init,z.getId());long afterNine=d.atTime(9,10).atZone(z).toInstant().toEpochMilli();crossed=new TodayFocus(memory).apply(TodayPlan.build(meds,Collections.emptyList(),Collections.emptyList(),afterNine,z.getId()),meds,Collections.emptyList(),Collections.emptyList(),afterNine,z.getId());eq(d.atTime(8,0).atZone(z).toInstant().toEpochMilli(),crossed.hero.get(0).plannedAt);eq(d.atTime(9,0).atZone(z).toInstant().toEpochMilli(),crossed.otherDue.get(0).plannedAt);
 Store.Log firstDone=new Store.Log();firstDone.medId=17;firstDone.plannedAt=d.atTime(8,0).atZone(z).toInstant().toEpochMilli();logs=Arrays.asList(firstDone);crossed=new TodayFocus(memory).apply(TodayPlan.build(meds,logs,Collections.emptyList(),d.atTime(13,0).atZone(z).toInstant().toEpochMilli(),z.getId()),meds,logs,Collections.emptyList(),d.atTime(13,0).atZone(z).toInstant().toEpochMilli(),z.getId());eq(d.atTime(9,0).atZone(z).toInstant().toEpochMilli(),crossed.hero.get(0).plannedAt);
 System.out.println("TodayFocusRegressionTest OK (clock pin, reopen, midnight, bootstrap, partial group, revision guards, newly due and intermediate advancement)");
 }
 static Store.Med med(long id,long rev,String times){Store.Med m=new Store.Med();m.id=id;m.revision=rev;m.name="Synthetic";m.dose="1 mg";m.times=times;m.scheduleMode=Store.FIXED;m.active=true;return m;}
 static final class Memory implements TodayFocus.State{String v="";public String get(){return v;}public void put(String s){v=s;}}
 static final class FileState implements TodayFocus.State{final java.io.File f;FileState(java.io.File f){this.f=f;}public String get(){try{return new String(java.nio.file.Files.readAllBytes(f.toPath()),java.nio.charset.StandardCharsets.UTF_8);}catch(Exception e){return "";}}public void put(String s){try{java.nio.file.Path parent=f.toPath().getParent();if(parent!=null)java.nio.file.Files.createDirectories(parent);java.nio.file.Files.write(f.toPath(),s.getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception e){throw new RuntimeException(e);}}}
}
